    let yesterday = calendar.date(byAdding: .day, value: -1, to: now)!
    if calendar.isDate(date, inSameDayAs: yesterday) { return "昨日" }
    if calendar.isDate(date, equalTo: now, toGranularity: .weekOfYear) { return "本周" }
